# Function to initialize the animation
def init():
    ax.set_xlim(-10, 10)
    ax.set_ylim(-10, 10)
    small_point.set_data([], [])
    large_point.set_data([], [])
    small_circle.center = (0, 0)
    large_circle.center = (0, 0)
    return small_point, large_point, small_circle, large_circle

# Function to update the frame
def update(frame):

    # Calculate the new center of the circle
    center_x = center_velocity * frame
    center_y = 0
    # Calculate the position of the point on the circle
    angle = angle_velocity * (-frame)
    small_point.set_data(center_x + small_radius * np.sin(np.radians(angle)), center_y - small_radius * np.cos(np.radians(angle)))
    large_point.set_data(center_x + large_radius * np.sin(np.radians(angle)), center_y - large_radius * np.cos(np.radians(angle)))
    # small_points.append((center_x + small_radius * np.sin(np.radians(angle)), center_y - small_radius * np.cos(np.radians(angle))))
    # large_points.append((center_x + large_radius * np.sin(np.radians(angle)), center_y - large_radius * np.cos(np.radians(angle))))

    small_circle.center = (center_x, center_y)
    large_circle.center = (center_x, center_y)

    # Set the aspect of the plot to equal, so the circle isn't distorted
    ax.set_aspect('equal', 'box')

    ax.set_xlim(-10, 10)
    ax.set_ylim(-10, 10)
    
    return small_point, large_point, small_circle, large_circle

# Create the animation
ani = animation.FuncAnimation(fig, update, frames=np.arange(0, 100, 0.1), init_func=init, blit=True)
